// Coleta de APs, rádios, clientes e redes Wi-Fi do UniFi Network 10.x.
// Só agregados: nenhum MAC, IP ou nome de aparelho de cliente é devolvido.
// Também não devolve campos sensíveis do controller (x_authkey, x_aes_gcm etc.):
// o JSON de saída é montado campo a campo.
var p = JSON.parse(value);
var base = String(p.url || '').replace(/\/+$/, '');
var site = p.site || 'default';
// '/proxy/network' no UniFi OS (console ou UniFi OS Server); vazio na Network Application standalone
var pre = String(p.prefix === undefined ? '/proxy/network' : p.prefix).replace(/\/+$/, '');
var weak = parseFloat(p.weak_signal || '-70');
if (!p.key) throw 'Macro {$UNIFI.API.KEY} vazia';

function get(path) {
  var r = new HttpRequest();
  r.addHeader('X-API-KEY: ' + p.key);
  r.addHeader('Accept: application/json');
  var body = r.get(base + path);
  var code = r.getStatus();
  if (code !== 200) throw 'HTTP ' + code + ' em ' + path + ': ' + String(body).substring(0, 200);
  return JSON.parse(body);
}
function num(v, d) { var n = parseFloat(v); return isNaN(n) ? (d === undefined ? -1 : d) : n; }
function r2(v) { return Math.round(v * 100) / 100; }

// nomes comerciais dos modelos (a API clássica devolve códigos como BZ2/U2Lv2)
var modelName = {};
try {
  var sites = get(pre + '/integration/v1/sites').data || [];
  var sid = null;
  for (var i = 0; i < sites.length; i++) if (sites[i].internalReference === site) sid = sites[i].id;
  if (sid) {
    var idv = get(pre + '/integration/v1/sites/' + sid + '/devices?limit=200').data || [];
    for (var j = 0; j < idv.length; j++) modelName[String(idv[j].macAddress).toLowerCase()] = idv[j].model;
  }
} catch (e) { }

var devs = get(pre + '/api/s/' + site + '/stat/device').data || [];
var stas = get(pre + '/api/s/' + site + '/stat/sta').data || [];
var wlans = get(pre + '/api/s/' + site + '/rest/wlanconf').data || [];

// clientes por AP e por SSID
var perAp = {}, perSsid = {};
var cs = { total: 0, wifi: 0, wired: 0, g2: 0, g5: 0, g6: 0, guest: 0, weak: 0, lowsat: 0, legacy: 0, sig: 0, sigN: 0, sat: 0, satN: 0, ret: 0, retN: 0 };
for (var k = 0; k < stas.length; k++) {
  var s = stas[k];
  cs.total++;
  if (s.is_wired) { cs.wired++; continue; }
  cs.wifi++;
  var band = s.radio === 'na' ? 'g5' : (s.radio === '6e' ? 'g6' : 'g2');
  cs[band]++;
  if (s.is_guest) cs.guest++;
  if (s.radio_proto === 'ng' || s.radio_proto === 'g' || s.radio_proto === 'b') cs.legacy++;
  var a = perAp[s.ap_mac] || (perAp[s.ap_mac] = { n: 0, weak: 0, sig: 0, sat: 0, satN: 0, ret: 0, retN: 0 });
  a.n++;
  if (typeof s.signal === 'number') {
    cs.sig += s.signal; cs.sigN++; a.sig += s.signal;
    if (s.signal < weak) { cs.weak++; a.weak++; }
  }
  if (typeof s.satisfaction === 'number') {
    cs.sat += s.satisfaction; cs.satN++; a.sat += s.satisfaction; a.satN++;
    if (s.satisfaction < 50) cs.lowsat++;
  }
  if (typeof s.wifi_tx_retries_percentage === 'number') {
    cs.ret += s.wifi_tx_retries_percentage; cs.retN++; a.ret += s.wifi_tx_retries_percentage; a.retN++;
  }
  var e = s.essid || '(sem nome)';
  var w = perSsid[e] || (perSsid[e] = { n: 0, sat: 0, satN: 0 });
  w.n++;
  if (typeof s.satisfaction === 'number') { w.sat += s.satisfaction; w.satN++; }
}

var aps = [], radios = [];
var sum = { total: 0, online: 0, offline: 0, eol: 0, upgradable: 0, uplink_limited: 0, fast_ethernet: 0, dualband: 0,
  r2: { n: 0, cu: 0, ret: 0, intf: 0 }, r5: { n: 0, cu: 0, ret: 0, intf: 0 } };
var now = Math.floor(Date.now() / 1000);
for (var d = 0; d < devs.length; d++) {
  var x = devs[d];
  if (x.type !== 'uap') continue;
  var mac = String(x.mac).toLowerCase();
  var up = x.uplink || {};
  var ss = x['system-stats'] || {};
  var ap = perAp[x.mac] || { n: 0, weak: 0, sig: 0, sat: 0, satN: 0, ret: 0, retN: 0 };
  var bands = {};
  var rts = x.radio_table_stats || [], rt = x.radio_table || [];
  for (var q = 0; q < rts.length; q++) {
    var rs = rts[q], cfg = {};
    for (var z = 0; z < rt.length; z++) if (rt[z].name === rs.name) cfg = rt[z];
    var bandName = rs.radio === 'na' ? '5 GHz' : (rs.radio === '6e' ? '6 GHz' : '2,4 GHz');
    bands[rs.radio] = 1;
    var cu = num(rs.cu_total, 0), self = num(rs.cu_self_rx, 0) + num(rs.cu_self_tx, 0);
    var intf = Math.max(0, cu - self);
    radios.push({
      key: mac + '-' + rs.radio, ap_mac: mac, ap_name: x.name || mac, radio: rs.radio, band: bandName,
      channel: num(rs.channel), width: cfg.ht ? parseInt(cfg.ht, 10) : -1, tx_power: num(rs.tx_power),
      tx_power_mode: cfg.tx_power_mode || '', cu_total: cu, cu_self_rx: num(rs.cu_self_rx, 0), cu_self_tx: num(rs.cu_self_tx, 0),
      interference: intf, clients: num(rs.num_sta, 0), satisfaction: num(rs.satisfaction),
      tx_retries_pct: num(rs.tx_retries_pct, 0), state: rs.state === 'RUN' ? 1 : 0,
      min_rssi: cfg.min_rssi_enabled ? num(cfg.min_rssi) : 0
    });
    var agg = rs.radio === 'na' ? sum.r5 : (rs.radio === 'ng' ? sum.r2 : null);
    if (agg && x.state === 1) { agg.n++; agg.cu += cu; agg.ret += num(rs.tx_retries_pct, 0); agg.intf += intf; }
  }
  var dual = (bands.na || bands['6e']) ? 1 : 0;
  sum.total++;
  if (x.state === 1) sum.online++; else sum.offline++;
  if (x.model_in_eol) sum.eol++;
  if (x.upgradable) sum.upgradable++;
  if (num(up.speed, 0) > 0 && num(up.max_speed, 0) > num(up.speed, 0)) sum.uplink_limited++;
  if (num(up.max_speed, 0) > 0 && num(up.max_speed, 0) <= 100) sum.fast_ethernet++;
  if (dual) sum.dualband++;
  aps.push({
    mac: mac, name: x.name || mac, model: modelName[mac] || x.model, model_code: x.model, ip: x.ip || '',
    state: num(x.state, 0), version: x.version || '', upgradable: x.upgradable ? 1 : 0,
    eol: x.model_in_eol ? 1 : 0, eol_date: x.model_eol_date ? String(x.model_eol_date).substring(0, 10) : '',
    dualband: dual, uptime: num(x.uptime, 0), last_seen_age: x.last_seen ? now - x.last_seen : -1,
    cpu: num(ss.cpu), mem: num(ss.mem), load1: x.sys_stats ? num(x.sys_stats.loadavg_1) : -1,
    clients: num(x.num_sta, 0), clients_guest: num(x['guest-num_sta'], 0), satisfaction: num(x.satisfaction),
    clients_weak: ap.weak, client_signal_avg: ap.n && ap.sig ? r2(ap.sig / ap.n) : 0,
    client_satisfaction_avg: ap.satN ? r2(ap.sat / ap.satN) : -1, client_retries_avg: ap.retN ? r2(ap.ret / ap.retN) : -1,
    uplink_type: up.type || '', uplink_speed: num(up.speed, 0), uplink_max_speed: num(up.max_speed, 0),
    uplink_full_duplex: up.full_duplex ? 1 : 0, uplink_tx_bps: Math.round(num(up['tx_bytes-r'], 0) * 8),
    uplink_rx_bps: Math.round(num(up['rx_bytes-r'], 0) * 8), uplink_rx_dropped: num(up.rx_dropped, 0),
    uplink_errors: num(up.rx_errors, 0) + num(up.tx_errors, 0)
  });
}

// redes Wi-Fi (configuração) + clientes por SSID
var wl = [], twoGOnly = 0;
for (var y = 0; y < wlans.length; y++) {
  var c = wlans[y], st = perSsid[c.name] || { n: 0, sat: 0, satN: 0 };
  var bandCfg = c.wlan_band || (c.wlan_bands ? c.wlan_bands.join('+') : 'both');
  if (c.enabled && bandCfg === '2g' && sum.dualband > 0) twoGOnly++;
  wl.push({
    ssid: c.name, enabled: c.enabled ? 1 : 0, band: bandCfg, security: c.security || '', wpa_mode: c.wpa_mode || '',
    pmf: c.pmf_mode || '', fast_roaming: c.fast_roaming_enabled ? 1 : 0, bss_transition: c.bss_transition ? 1 : 0,
    min_rate_kbps: num(c.minrate_ng_data_rate_kbps, 0), hidden: c.hide_ssid ? 1 : 0, guest: c.is_guest ? 1 : 0,
    clients: st.n, satisfaction: st.satN ? r2(st.sat / st.satN) : -1
  });
}

function avg(a, f) { return a.n ? r2(a[f] / a.n) : -1; }
return JSON.stringify({
  aps: aps, radios: radios, wlans: wl,
  summary: {
    aps_total: sum.total, aps_online: sum.online, aps_offline: sum.offline, aps_eol: sum.eol,
    aps_upgradable: sum.upgradable, aps_uplink_limited: sum.uplink_limited, aps_fast_ethernet: sum.fast_ethernet,
    aps_dualband: sum.dualband, wlans_2g_only_with_dualband: twoGOnly,
    clients_total: cs.total, clients_wifi: cs.wifi, clients_wired: cs.wired, clients_2g: cs.g2, clients_5g: cs.g5,
    clients_6g: cs.g6, clients_guest: cs.guest, clients_weak: cs.weak,
    clients_weak_pct: cs.wifi ? r2(cs.weak * 100 / cs.wifi) : 0, clients_low_satisfaction: cs.lowsat,
    clients_legacy: cs.legacy, clients_signal_avg: cs.sigN ? r2(cs.sig / cs.sigN) : 0,
    clients_satisfaction_avg: cs.satN ? r2(cs.sat / cs.satN) : -1, clients_retries_avg: cs.retN ? r2(cs.ret / cs.retN) : -1,
    radio2g_cu_avg: avg(sum.r2, 'cu'), radio2g_retries_avg: avg(sum.r2, 'ret'), radio2g_interference_avg: avg(sum.r2, 'intf'),
    radio5g_cu_avg: avg(sum.r5, 'cu'), radio5g_retries_avg: avg(sum.r5, 'ret'), radio5g_interference_avg: avg(sum.r5, 'intf')
  }
});

// Coleta do controller e da experiência Wi-Fi do site (UniFi Network 10.x):
// versão/atualização, conexões (24 h), faixas de experiência, retransmissões,
// vizinhança de rádio, otimizações pendentes e dispositivos aguardando adoção.
// Só agregados: nenhum MAC ou nome de cliente é devolvido.
var p = JSON.parse(value);
var base = String(p.url || '').replace(/\/+$/, '');
var site = p.site || 'default';
// '/proxy/network' no UniFi OS (console ou UniFi OS Server); vazio na Network Application standalone
var pre = String(p.prefix === undefined ? '/proxy/network' : p.prefix).replace(/\/+$/, '');
var strong = parseFloat(p.strong_neighbor || '-70');
if (!p.key) throw 'Macro {$UNIFI.API.KEY} vazia';

function get(path, optional) {
  var r = new HttpRequest();
  r.addHeader('X-API-KEY: ' + p.key);
  r.addHeader('Accept: application/json');
  var body = r.get(base + path);
  var code = r.getStatus();
  if (code !== 200) {
    if (optional) return null;
    throw 'HTTP ' + code + ' em ' + path + ': ' + String(body).substring(0, 200);
  }
  return JSON.parse(body);
}
function num(v, d) { var n = parseFloat(v); return isNaN(n) ? (d === undefined ? -1 : d) : n; }
function r2(v) { return Math.round(v * 100) / 100; }

var out = {};
var si = (get(pre + '/api/s/' + site + '/stat/sysinfo').data || [{}])[0];
out.version = si.version || '';
out.uptime = num(si.uptime, 0);
out.update_available = si.update_available ? 1 : 0;
out.name = si.name || '';

var health = get(pre + '/api/s/' + site + '/stat/health').data || [];
out.wlan_status = '';
for (var h = 0; h < health.length; h++) if (health[h].subsystem === 'wlan') out.wlan_status = health[h].status || '';

var pend = get(pre + '/integration/v1/pending-devices', true);
out.pending_devices = pend && pend.totalCount !== undefined ? pend.totalCount : -1;

// Conexões nas últimas 24 h (latências da API em microssegundos → segundos)
var wc = get(pre + '/v2/api/site/' + site + '/wifi-connectivity', true) || {};
var at = wc.attempts || {}, lt = wc.latencies || {};
out.conn_attempts = num(at.total_attempts, 0);
out.conn_failed = num(at.failed_client_connections, 0);
out.conn_success_pct = num(at.success_ratio);
out.conn_assoc_pct = num(at.association_ratio);
out.conn_auth_pct = num(at.authentication_ratio);
out.conn_dhcp_pct = num(at.dhcp_ratio);
out.conn_dns_pct = num(at.dns_ratio);
out.conn_latency_total = lt.total_latency ? r2(lt.total_latency / 1e6) : -1;
out.conn_latency_assoc = lt.association_latency ? r2(lt.association_latency / 1e6) : -1;
out.conn_latency_auth = lt.authentication_latency ? r2(lt.authentication_latency / 1e6) : -1;
out.conn_latency_dhcp = lt.dhcp_latency ? r2(lt.dhcp_latency / 1e6) : -1;
out.clients_24h = num(wc.total_clients, 0);

// Experiência dos clientes (% das sessões por faixa de satisfação) e retransmissões
var ag = get(pre + '/v2/api/site/' + site + '/aggregated-dashboard', true) || {};
var cats = (ag.wifi_client_experience || {}).categories || [];
var good = 0, fair = 0, poor = 0;
for (var c = 0; c < cats.length; c++) {
  var pct = num(cats[c].session_percentage, 0), id = cats[c].category_id;
  if (id >= 80) good += pct; else if (id >= 60) fair += pct; else poor += pct;
}
out.experience_good_pct = r2(good);
out.experience_fair_pct = r2(fair);
out.experience_poor_pct = r2(poor);
var rc = (ag.wifi_tx_retries || {}).categories || [], highRet = 0;
for (var t = 0; t < rc.length; t++) if (rc[t].category_id >= 15) highRet += num(rc[t].band_count, 0);
out.radios_high_retries = highRet;
var doc = (ag.wifi_doctor || {}).actions || [], docPend = 0, docList = [];
for (var a = 0; a < doc.length; a++) if (doc[a].optimization_status === 'PENDING') { docPend++; docList.push(doc[a].id); }
out.doctor_pending = docPend;
out.doctor_pending_list = docList.join(', ');

// Vizinhança de rádio (redes de terceiros ouvidas pelos APs)
var ro = get(pre + '/api/s/' + site + '/stat/rogueap', true) || {};
var rl = ro.data || [];
var n = { total: 0, g2: 0, g5: 0, g2strong: 0, g5strong: 0, c1: 0, c6: 0, c11: 0 };
for (var r = 0; r < rl.length; r++) {
  var x = rl[r];
  if (x.is_ubnt) continue;
  n.total++;
  var sig = num(x.signal, -200);
  if (x.radio === 'ng') {
    n.g2++;
    if (sig >= strong) {
      n.g2strong++;
      if (x.channel <= 3) n.c1++; else if (x.channel <= 8) n.c6++; else n.c11++;
    }
  } else if (x.radio === 'na' || x.radio === '6e') {
    n.g5++;
    if (sig >= strong) n.g5strong++;
  }
}
out.neighbors_total = n.total;
out.neighbors_2g = n.g2;
out.neighbors_5g = n.g5;
out.neighbors_2g_strong = n.g2strong;
out.neighbors_5g_strong = n.g5strong;
out.neighbors_2g_strong_ch1 = n.c1;
out.neighbors_2g_strong_ch6 = n.c6;
out.neighbors_2g_strong_ch11 = n.c11;
return JSON.stringify(out);
